program:
(()=>{

const $ = id => document.getElementById(id);
const WA = FMI.phone;           /* the family's WhatsApp in a real invitation */
const TARGET = FMI.target;
const calm = FMI.reduceMotion || matchMedia("(prefers-reduced-motion: reduce)").matches;
const params = new URLSearchParams(FMI.search);
const preview = false;

/* guest name from ?to=Kumar-Family */
let guest = "";
try {
  guest = (params.get("to") || "").replace(/[-_+]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 40);
  guest = guest.split(" ").map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
} catch (e) {}
if (guest) {
  ["dear", "g-dear"].forEach(id => { $(id).textContent = "Dear " + guest + ","; $(id).hidden = false; });
  $("r-name").value = guest;
  document.title = "Dear " + guest + " · Hari & Kavya's Housewarming";
}

/* scroll engine: each scene gets --p from 0 to 1 */
const scenes = [...document.querySelectorAll("[data-scene]")];
const root = document.documentElement;
let ticking = false;
const CALM_P = { "s-plan": .5, "s-door": .3, "s-in": .25, "s-night": .7 };
function update(){
  const vh = innerHeight;
  for (const s of scenes) {
    const r = s.getBoundingClientRect();
    let p = calm ? CALM_P[s.id] : -r.top / Math.max(1, r.height - vh);
    p = Math.min(1, Math.max(0, p));
    s.style.setProperty("--p", p.toFixed(4));
  }
  const max = root.scrollHeight - vh;
  root.style.setProperty("--gp", max > 0 ? (scrollY / max).toFixed(4) : 0);
  ticking = false;
}
addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
addEventListener("resize", update);
update();

/* reveal on view */
const io = "IntersectionObserver" in window ? new IntersectionObserver(es => es.forEach(e => {
  if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
}), { threshold: .15 }) : null;
document.querySelectorAll(".rv").forEach(el => io ? io.observe(el) : el.classList.add("in"));

/* sounds, made in the browser */
let actx;
function ac(){ try { actx = actx || new (window.AudioContext || window.webkitAudioContext)(); if (actx.state === "suspended") actx.resume(); } catch (e) {} return actx; }
function tone(base, gain, when, parts){
  const c = ac(); if (!c) return;
  try {
    const t0 = c.currentTime + .02 + (when || 0), out = c.createGain(); out.gain.value = gain || .08; out.connect(c.destination);
    (parts || [[1, 1, 2.4], [2, .4, 1.6], [3, .16, 1.1], [4.2, .07, .7]]).forEach(([r, g, d]) => {
      const o = c.createOscillator(); o.type = "sine"; o.frequency.value = base * r;
      const v = c.createGain(); v.gain.setValueAtTime(0, t0); v.gain.linearRampToValueAtTime(g, t0 + .008); v.gain.exponentialRampToValueAtTime(.0001, t0 + d);
      o.connect(v); v.connect(out); o.start(t0); o.stop(t0 + d + .05);
    });
  } catch (e) {}
}
const BELL = [[1, 1, 3.2], [2.76, .45, 2.2], [5.4, .25, 1.4], [8.9, .1, .8]];
function templeBell(f, g, w){ tone(f || 880, g || .07, w, BELL); }
function click(){
  const c = ac(); if (!c) return;
  try {
    const n = Math.floor(c.sampleRate * .05), b = c.createBuffer(1, n, c.sampleRate), ch = b.getChannelData(0);
    for (let i = 0; i < n; i++) ch[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / n, 8);
    const s = c.createBufferSource(); s.buffer = b; const f = c.createBiquadFilter(); f.type = "bandpass"; f.frequency.value = 2600; f.Q.value = 2;
    const g = c.createGain(); g.gain.value = .9; s.connect(f); f.connect(g); g.connect(c.destination); s.start();
  } catch (e) {}
}

/* music: starts with the key, toggled from the corner button */
const music = $("music"), mBtn = $("music-btn");
let musicWanted = false;
function paintMusic(){ mBtn.classList.toggle("on", musicWanted); mBtn.setAttribute("aria-pressed", musicWanted); mBtn.setAttribute("aria-label", musicWanted ? "Pause music" : "Play music"); }
function setMusic(on){
  musicWanted = on;
  if (on) { music.volume = .75; const p = music.play(); if (p) p.catch(() => { musicWanted = false; paintMusic(); }); }
  else music.pause();
  paintMusic();
}
mBtn.addEventListener("click", () => setMusic(!musicWanted));
document.addEventListener("visibilitychange", () => { if (document.hidden) music.pause(); else if (musicWanted) music.play().catch(() => {}); });

/* gate: the key turns with a click and a warm light opens the invitation */
const gate = $("gate");
let opened = false;
function turnKey(){
  if (opened) return; opened = true;
  ac(); setMusic(true); mBtn.hidden = false;
  gate.classList.add("turn");
  setTimeout(click, calm ? 0 : 420); setTimeout(() => templeBell(1046.5, .06), calm ? 0 : 520);
  setTimeout(() => { document.body.classList.remove("locked"); gate.classList.add("gone"); update(); }, calm ? 300 : 1500);
  setTimeout(() => { gate.hidden = true; }, calm ? 1200 : 2500);
}
$("open").addEventListener("click", turnKey);
$("g-key").addEventListener("click", turnKey);
if (preview) { gate.hidden = true; document.body.classList.remove("locked"); }

/* countdown */
const cells = {}; document.querySelectorAll("#count b").forEach(b => cells[b.dataset.u] = b);
function tick(){
  let s = Math.floor((TARGET - Date.now()) / 1000);
  if (s <= 0) { $("count").innerHTML = '<p style="grid-column:1/-1;font-size:1.3rem;font-style:italic">We are home! Thank you for your blessings.</p>'; return; }
  const d = Math.floor(s / 86400); s -= d * 86400;
  const h = Math.floor(s / 3600); s -= h * 3600;
  const m = Math.floor(s / 60); s -= m * 60;
  cells.d.textContent = d;
  cells.h.textContent = String(h).padStart(2, "0");
  cells.m.textContent = String(m).padStart(2, "0");
  cells.s.textContent = String(s).padStart(2, "0");
  setTimeout(tick, 1000 - Date.now() % 1000);
}
tick();

/* light the lamp: the centre wick first, then the pairs */
const lamp = $("lamp"), flames = [...lamp.querySelectorAll(".fl")];
let lit = false;
function lightLamp(){
  const text = $("b-text").value.trim();
  if (!lit) {
    lit = true;
    flames.forEach((f, i) => setTimeout(() => { f.classList.add("on"); lamp.style.setProperty("--lit", i + 1); templeBell([784, 880, 880, 1046.5, 1046.5][i], .05); }, calm ? 0 : [0, 380, 380, 760, 760][i] + (i % 2 ? 0 : 60)));
  } else templeBell(880, .06);
  $("bless-msg").textContent = "Thank you" + (guest ? ", " + guest : "") + "! Your light now shines in our home.";
  const msg = "Blessings for Hari, Kavya & Tara's new home 🪔\n\n" + (text || "May your new home be filled with light, love and happiness.") + (guest ? "\n\nWith love,\n" + guest : "");
  $("bless-wa").href = "https://wa.me/" + WA + "?text=" + encodeURIComponent(msg); $("bless-wa").hidden = false;
}
lamp.addEventListener("click", lightLamp);
$("bless-form").addEventListener("submit", e => { e.preventDefault(); lightLamp(); });

/* the doorbell */
$("ding").addEventListener("click", () => {
  tone(659.25, .1, 0, [[1, 1, 1.4], [2, .3, .9], [3, .1, .5]]); tone(523.25, .1, .42, [[1, 1, 1.8], [2, .3, 1.1], [3, .1, .6]]);
  const b = $("bells"); b.classList.remove("ring"); void b.offsetWidth; b.classList.add("ring");
});

/* calendar: Apple devices open the .ics, others get Google Calendar */
const CAL = FMI.calendar({
  puja:  { t: "Hari & Kavya · Housewarming puja", d: "20270210T010000Z/20270210T030000Z", l: "No. 14, Sunrise Avenue, Pallikaranai, Chennai" },
  lunch: { t: "Hari & Kavya · Housewarming lunch", d: "20270210T063000Z/20270210T090000Z", l: "No. 14, Sunrise Avenue, Pallikaranai, Chennai" }
});
if (!/iPhone|iPad|iPod|Macintosh/.test(navigator.userAgent)) document.querySelectorAll("[data-cal]").forEach(a => {
  const c = CAL[a.dataset.cal];
  a.href = "https://calendar.google.com/calendar/render?action=TEMPLATE&text=" + encodeURIComponent(c.t) + "&dates=" + c.d + "&location=" + encodeURIComponent(c.l) + "&details=" + encodeURIComponent("Invitation: https://findmyinvite.com/");
  a.target = "_blank"; a.rel = "noopener";
});

/* rsvp */
let guests = 2;
$("g-minus").addEventListener("click", () => { guests = Math.max(1, guests - 1); $("g-count").textContent = guests; });
$("g-plus").addEventListener("click", () => { guests = Math.min(20, guests + 1); $("g-count").textContent = guests; });
const form = $("rsvp-form");
form.addEventListener("change", () => {
  $("att-yes").style.display = form.querySelector("input[name=att]:checked").value === "yes" ? "grid" : "none";
});
form.addEventListener("submit", e => {
  e.preventDefault();
  const name = $("r-name").value.trim();
  if (!name) { $("r-err").hidden = false; $("r-name").focus(); return; }
  $("r-err").hidden = true;
  const yes = form.querySelector("input[name=att]:checked").value === "yes";
  const lines = ["RSVP · Hari & Kavya's Housewarming 🏡", "", "Name: " + name, "Coming: " + (yes ? "Yes, we'll be there" : "Sorry, can't make it")];
  if (yes) {
    lines.push("For: " + ([...form.querySelectorAll("input[name=fn]:checked")].map(i => i.value).join(", ") || "Not sure yet"));
    lines.push("Guests: " + guests);
  }
  const w = $("r-msg").value.trim(); if (w) lines.push("Note: " + w);
  const url = "https://wa.me/" + WA + "?text=" + encodeURIComponent(lines.join("\n"));
  const win = FMI.open(url, "_blank"); if (!win) FMI.open(url);
});

/* share */
function toast(t){ const el = $("toast"); el.textContent = t; el.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => el.hidden = true, 2200); }
$("share").addEventListener("click", async () => {
  const url = location.origin + FMI.instanceKey;
  try {
    if (navigator.share) { await FMI.share({ title: "Hari & Kavya · Housewarming Invitation", text: "You're invited to Hari & Kavya's housewarming on 10 February 2027", url }); return; }
    await FMI.copyLink(url); toast("Invitation link copied");
  } catch (e) { if (e && e.name !== "AbortError") toast(url); }
});

FMI.ready();
})();
